import{b as i,O as a,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const E=JSON.parse('{"title":"筛选与排序","description":"","frontmatter":{},"headers":[],"relativePath":"database/mysql/query/filter-sort/index.md","filePath":"数据库管理/MySQL必知必会/2.数据查询/02.筛选与排序.md","lastUpdated":1782225202000}'),h={name:"database/mysql/query/filter-sort/index.md"};function l(d,s,n,p,k,r){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="筛选与排序" tabindex="-1">筛选与排序 <a class="header-anchor" href="#筛选与排序" aria-label="Permalink to &quot;筛选与排序&quot;">​</a></h1><blockquote><p>WHERE过滤、比较运算、NULL值判断、ORDER BY排序</p></blockquote><h2 id="where-按条件筛选" tabindex="-1">WHERE：按条件筛选 <a class="header-anchor" href="#where-按条件筛选" aria-label="Permalink to &quot;WHERE：按条件筛选&quot;">​</a></h2><p>上一章学会了 <code>SELECT ... FROM</code> 拿数据，但每次都拿全表。现实场景通常是&quot;查北京的所有员工&quot;、&quot;找工资大于 10000 的人&quot;——这就要靠 <code>WHERE</code>。</p><h3 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;北京&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>name</th><th>city</th></tr></thead><tbody><tr><td>张三</td><td>北京</td></tr><tr><td>孙七</td><td>北京</td></tr><tr><td>郑十</td><td>北京</td></tr></tbody></table><p><code>WHERE city = &#39;北京&#39;</code> 的意思是：MySQL 一行行检查，<code>city</code> 是&quot;北京&quot;的留下，不是的跳过。</p><blockquote><p>💡 注意字符串用<strong>单引号</strong>，<code>&#39;北京&#39;</code> 对，<code>&quot;北京&quot;</code> 也能跑但不推荐（和 SQL 标准有差异）。</p></blockquote><h2 id="比较运算符" tabindex="-1">比较运算符 <a class="header-anchor" href="#比较运算符" aria-label="Permalink to &quot;比较运算符&quot;">​</a></h2><p><code>=</code> 只是冰山一角，WHERE 支持的运算符很多：</p><table tabindex="0"><thead><tr><th>运算符</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><code>=</code></td><td>等于</td><td><code>WHERE age = 25</code></td></tr><tr><td><code>&lt;&gt;</code> 或 <code>!=</code></td><td>不等于</td><td><code>WHERE city &lt;&gt; &#39;北京&#39;</code></td></tr><tr><td><code>&lt;</code></td><td>小于</td><td><code>WHERE salary &lt; 10000</code></td></tr><tr><td><code>&lt;=</code></td><td>小于等于</td><td><code>WHERE age &lt;= 30</code></td></tr><tr><td><code>&gt;</code></td><td>大于</td><td><code>WHERE salary &gt; 10000</code></td></tr><tr><td><code>&gt;=</code></td><td>大于等于</td><td><code>WHERE age &gt;= 28</code></td></tr><tr><td><code>BETWEEN</code></td><td>在范围内</td><td><code>WHERE age BETWEEN 25 AND 30</code></td></tr></tbody></table><h3 id="不等于" tabindex="-1">不等于 <a class="header-anchor" href="#不等于" aria-label="Permalink to &quot;不等于&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;北京&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>北京以外的所有人。</p><h3 id="范围查询" tabindex="-1">范围查询 <a class="header-anchor" href="#范围查询" aria-label="Permalink to &quot;范围查询&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BETWEEN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><code>BETWEEN a AND b</code> 是<strong>闭区间</strong>，包含 <code>a</code> 和 <code>b</code>。上面等价于 <code>salary &gt;= 8000 AND salary &lt;= 12000</code>。</p><h2 id="null-值判断" tabindex="-1">NULL 值判断 <a class="header-anchor" href="#null-值判断" aria-label="Permalink to &quot;NULL 值判断&quot;">​</a></h2><p>表里有些字段可能是空的——不是 <code>0</code>，不是 <code>&#39;&#39;</code>，是 <code>NULL</code>。</p><p><code>NULL</code> 表示&quot;未知&quot;或&quot;没有值&quot;。查 NULL <strong>不能用 <code>=</code></strong>：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ❌ 错误：永远查不出结果</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ✅ 正确</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>同理，查非空用 <code>IS NOT NULL</code>：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><blockquote><p>⚠️ <strong>为什么 <code>= NULL</code> 不行</strong>：SQL 里 <code>NULL</code> 代表&quot;未知&quot;，一个未知值和另一个未知值无法判断相等。所以专门设计了 <code>IS NULL</code> 来判断。</p></blockquote><h2 id="order-by-排序" tabindex="-1">ORDER BY：排序 <a class="header-anchor" href="#order-by-排序" aria-label="Permalink to &quot;ORDER BY：排序&quot;">​</a></h2><p>查出来的数据默认按存储顺序排列，想按某个规则排就用 <code>ORDER BY</code>。</p><h3 id="单列排序" tabindex="-1">单列排序 <a class="header-anchor" href="#单列排序" aria-label="Permalink to &quot;单列排序&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> salary;</span></span></code></pre></div><p>默认<strong>升序（ASC）</strong>，工资从低到高：</p><table tabindex="0"><thead><tr><th>name</th><th>salary</th></tr></thead><tbody><tr><td>孙七</td><td>6000.00</td></tr><tr><td>郑十</td><td>7800.00</td></tr><tr><td>张三</td><td>8000.00</td></tr><tr><td>...</td><td>...</td></tr></tbody></table><p>降序加 <code>DESC</code>：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>工资从高到低。</p><h3 id="多列排序" tabindex="-1">多列排序 <a class="header-anchor" href="#多列排序" aria-label="Permalink to &quot;多列排序&quot;">​</a></h3><p>先按城市排，同一城市内再按工资排：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, city, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>name</th><th>city</th><th>salary</th></tr></thead><tbody><tr><td>郑十</td><td>北京</td><td>7800.00</td></tr><tr><td>张三</td><td>北京</td><td>8000.00</td></tr><tr><td>孙七</td><td>北京</td><td>6000.00</td></tr></tbody></table><blockquote><p>← 错了？不，注意 <code>DESC</code> 只对 salary 生效</p></blockquote><blockquote><p>⚠️ <code>DESC</code> 只作用于它前面的那一列。如果 city 也要降序，得写成 <code>ORDER BY city DESC, salary DESC</code>。</p></blockquote><h2 id="order-by-limit-取极值" tabindex="-1">ORDER BY + LIMIT：取极值 <a class="header-anchor" href="#order-by-limit-取极值" aria-label="Permalink to &quot;ORDER BY + LIMIT：取极值&quot;">​</a></h2><p>组合这两招能解决很多实际问题。</p><h3 id="工资最高的-3-个人" tabindex="-1">&quot;工资最高的 3 个人&quot; <a class="header-anchor" href="#工资最高的-3-个人" aria-label="Permalink to &quot;&quot;工资最高的 3 个人&quot;&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h3 id="年龄最小的-2-个人" tabindex="-1">&quot;年龄最小的 2 个人&quot; <a class="header-anchor" href="#年龄最小的-2-个人" aria-label="Permalink to &quot;&quot;年龄最小的 2 个人&quot;&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h3 id="第-4-6-名工资的人" tabindex="-1">第 4-6 名工资的人 <a class="header-anchor" href="#第-4-6-名工资的人" aria-label="Permalink to &quot;第 4-6 名工资的人&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><blockquote><p>📝 <strong>WHERE、ORDER BY、LIMIT 的执行顺序</strong>：WHERE 筛选 → ORDER BY 排序 → LIMIT 截取。所以 <code>LIMIT</code> 拿到的是&quot;筛选并排好序&quot;之后的前 N 行。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这章让查询从&quot;全捞出来&quot;进化到了&quot;挑着看&quot;：</p><ol><li><strong>WHERE 是筛子</strong> — 想查谁查谁，不用全表扫描</li><li><strong>比较运算符</strong> — <code>=</code> <code>&lt;&gt;</code> <code>&gt;</code> <code>BETWEEN</code>，数字和字符串的写法不一样</li><li><strong>NULL 用 IS NULL / IS NOT NULL</strong> — 普通比较对 NULL 无效</li><li><strong>ORDER BY 排序</strong> — 默认 ASC，DESC 是降序，可以多列排序</li><li><strong>ORDER BY + LIMIT 取极值</strong> — 最高工资前 3 名、最新注册的 5 个人，都是这个组合</li></ol><blockquote><p>💡 WHERE 是 SQL 里使用频率最高的子句，把它写顺手了，后面联表、子查询才能顺滑。</p></blockquote><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>查所有不在北京的员工</li><li>查工资在 8000 到 12000 之间的人</li><li>查年龄大于 28 岁的员工，按年龄降序排列</li><li>找出工资最低的 2 个人</li><li>查 city 不为空的员工（数据都有 city，但试试 <code>IS NOT NULL</code>）</li></ol>`,55)])])}const c=i(h,[["render",l]]);export{E as __pageData,c as default};
